  'faq_a1' => 'APS Dream Home has been serving users in Gorakhpur and surrounding areas for over 8 years. We have established ourselves as a trusted name in real estate with a proven track record of successful projects and satisfied users.',
  'faq_a10' => 'Yes, we offer comprehensive property management services including tenant screening, rent collection, maintenance coordination, and property inspections. Our property management team ensures your investment is well-maintained and profitable.',
  'faq_a11' => 'Absolutely! We provide end-to-end legal assistance including property registration, documentation, stamp duty payment, and liaison with government authorities. Our legal team ensures all paperwork is completed accurately and efficiently.',
  'faq_a12' => 'Yes, we have partnered with experienced interior designers who can help transform your new property into your dream home. We offer customized interior design packages that suit various budgets and preferences.',
  'faq_a13' => 'We provide comprehensive after-sales support including property handover assistance, defect rectification (within warranty period), maintenance guidance, and ongoing customer support. Our relationship with users continues long after the sale is completed.',
  'faq_a14' => 'Yes, we provide structural warranty on all our construction projects. The warranty period varies by project type and will be specified in your sale agreement. We also offer extended warranty options for additional peace of mind.',
  'faq_a15' => 'You can contact our customer support team through multiple channels:',
  'faq_a15_email' => 'Email: support@apsdreamhome.com',
  'faq_a15_hours' => 'Our support team is available Monday to Saturday, 9:00 AM to 7:00 PM.',
  'faq_a15_office' => 'Visit our office in Gorakhpur',
  'faq_a15_phone' => 'Phone: +91-7007444842',
  'faq_a15_web' => 'Through our website contact form',
  'faq_a2' => 'We primarily serve Gorakhpur and surrounding areas in Uttar Pradesh. We also have projects in Lucknow, Varanasi, and Allahabad. Our expertise covers residential, commercial, and plot developments across these regions.',
  'faq_a3' => 'Yes, APS Dream Home is a fully licensed and registered real estate company. We comply with all local regulations and maintain proper documentation for all our projects. Our registration and licensing information is available upon request.',
  'faq_a4' => 'We offer a wide range of properties including residential apartments, independent houses, villas, commercial spaces, and plots. Our portfolio includes both ready-to-move-in properties and under-construction projects.',
  'faq_a5' => 'All our properties undergo thorough legal verification. We provide complete documentation including title deeds, approved building plans, occupancy certificates, and other necessary legal clearances. Our legal team ensures every property meets all regulatory requirements.',
  'faq_a6' => 'Absolutely! We encourage site visits for all our properties. Our sales team can arrange property visits at convenient times. We believe in complete transparency and want you to see exactly what you\'re investing in.',
  'faq_a7' => 'Property prices typically include the base cost of the property, registration fees, and basic amenities. Additional costs like stamp duty, legal fees, and maintenance charges (if applicable) are separate and will be clearly explained during the buying process.',
  'faq_a8' => 'Yes, we have tie-ups with major banks and financial institutions. Our team can help you with home loan applications, documentation, and getting the best interest rates. We guide you through the entire financing process.',
  'faq_a9' => 'Yes, a refundable booking amount is typically required to reserve a property. This amount varies by property value and will be adjusted against the total payment once the sale is finalized. All booking amounts are fully refundable if you decide not to proceed.',
  'faq_q1' => 'How long has APS Dream Home been in business?',
  'faq_q10' => 'Do you provide property management services?',
  'faq_q11' => 'Can you help with property registration and legal formalities?',
  'faq_q12' => 'Do you offer interior design services?',
  'faq_q13' => 'What kind of after-sales support do you provide?',
  'faq_q14' => 'Is there a warranty on construction quality?',
  'faq_q15' => 'How can I contact customer support?',
  'faq_q2' => 'What areas do you serve?',
  'faq_q3' => 'Are you licensed and registered?',
  'faq_q4' => 'What types of properties do you offer?',
  'faq_q5' => 'How do I know if a property is legally cleared?',
  'faq_q6' => 'Can I visit the property before purchasing?',
  'faq_q7' => 'What is included in the property price?',
  'faq_q8' => 'Do you offer home loans or financing options?',
  'faq_q9' => 'Is there a booking amount required?',
  'faq_title' => 'Frequently Asked Questions',
