  'assoc_mlm_faq_title' => 'Frequently Asked Questions',
  'assoc_mlm_faq1_q' => 'How do I register as an Associate?',
  'assoc_mlm_faq1_a' => 'Click on "Register as Associate" or ask your existing associate for their referral link. Complete the registration form with your basic details. You\'ll receive your unique referral link immediately after registration.',
  'assoc_mlm_faq2_q' => 'When do I get paid?',
  'assoc_mlm_faq2_a' => 'Commissions are calculated automatically when a payment is received for a plot booking. Payouts are processed in monthly batches. You can track all your earnings in the Commissions section of your dashboard.',
  'assoc_mlm_faq3_q' => 'Is there a cap on earnings?',
  'assoc_mlm_faq3_a' => 'Yes, the total commission per sale is capped at 20% of the sale value. This cap ensures sustainability while still providing excellent earning potential. The 2% Royalty Pool for VP+ ranks is outside this cap.',
  'assoc_mlm_faq4_q' => 'Can I lose my rank?',
  'assoc_mlm_faq4_a' => 'No — once you achieve a rank, you keep it. Ranks only go up, never down. Monthly evaluations check if you qualify for the next rank based on team size and qualifying volume.',
  'assoc_mlm_faq5_q' => 'What is the difference between direct commission and differential commission?',
  'assoc_mlm_faq5_a' => '<strong>Direct commission</strong> is what the agent who makes the sale earns (5-20% based on rank). <strong>Differential commission</strong> is what upline members earn — the difference between their rank\'s rate and the direct agent\'s rate. For example, if you\'re a BDM (10%) and your downline Associate (5%) makes a sale, you earn the 5% difference. The total never exceeds your rank\'s rate.',
  'assoc_mlm_faq6_q' => 'What if a booking is cancelled?',
  'assoc_mlm_faq6_a' => 'If a booking is cancelled, all commissions paid against that booking are clawed back (reversed). This keeps the system fair and prevents earning on cancelled transactions.',
  'assoc_mlm_your_ref_link' => 'Your Referral Link',
  'assoc_mlm_share_desc' => 'Share this link with potential associates to grow your team:',
  'assoc_mlm_copy' => 'Copy',
