  'assoc_rank_term1_q' => 'How is rank calculated?',
  'assoc_rank_term1_a' => 'Rank is calculated based on <strong>lifetime business volume</strong> (total plot sales value) and <strong>team size</strong> (number of direct legs). Both criteria must be met for promotion. Evaluation happens at month end.',
  'assoc_rank_term2_q' => 'When do I get my rank reward?',
  'assoc_rank_term2_a' => 'Rank rewards are delivered within <strong>30 days</strong> of achieving and maintaining the rank for <strong>3 consecutive months</strong>. Rewards are non-transferable and subject to tax deduction at source.',
  'assoc_rank_term3_q' => 'What counts as a "direct leg"?',
  'assoc_rank_term3_a' => 'A direct leg is an associate who has registered using your referral code and has made at least <strong>one sale</strong>. Inactive associates (no sales in 3 months) are not counted toward team requirements.',
  'assoc_rank_term4_q' => 'Can I lose my rank?',
  'assoc_rank_term4_a' => 'Yes. If your <strong>monthly business volume</strong> drops below the minimum threshold for <strong>2 consecutive months</strong>, your rank will be reviewed. You will be given a 1-month grace period to recover.',
  'assoc_rank_term5_q' => 'How is business volume calculated?',
  'assoc_rank_term5_a' => 'Business volume includes the <strong>total plot value</strong> of all bookings made by you and your team. Only confirmed/completed bookings count. Cancelled or refunded bookings are excluded.',

